<?php
$dispatchId=(int)($_GET['id']??0);
$dispatchSql='SELECT r.*,b.name branch_name,requester.name requester_name,sender.name sender_name,receiver.name receiver_name FROM stock_requests r JOIN branches b ON b.id=r.branch_id JOIN users requester ON requester.id=r.requested_by LEFT JOIN users sender ON sender.id=r.sent_by LEFT JOIN users receiver ON receiver.id=r.received_by WHERE r.id=? AND r.status IN (\'shipped\',\'received\',\'closed\')'.(currentLocation()?' AND r.branch_id='.currentLocation():'').' LIMIT 1';
$dispatchQuery=db()->prepare($dispatchSql);
$dispatchQuery->execute([$dispatchId]);
$dispatch=$dispatchQuery->fetch();
if(!$dispatch){http_response_code(404);exit('Բաշխման փաստաթուղթը չի գտնվել։');}
$itemQuery=db()->prepare('SELECT i.requested_qty,i.approved_qty,p.code,p.name,p.unit FROM request_items i JOIN products p ON p.id=i.product_id WHERE i.request_id=? ORDER BY i.id');
$itemQuery->execute([$dispatchId]);
$dispatchItems=$itemQuery->fetchAll();
?>
