<?php if(trim((string)$dispatch['reason'])!==''):?><p class="reason"><small>Պահանջի հիմնավորում</small><?=h($dispatch['reason'])?></p><?php endif?>
<table class="items"><thead><tr><th>Կոդ</th><th>Ապրանք</th><th>Պահանջված</th><th>Ուղարկված</th><th>Միավոր</th></tr></thead><tbody><?php foreach($dispatchItems as $dispatchItem):?><tr><td><?=h($dispatchItem['code'])?></td><td><?=h($dispatchItem['name'])?></td><td class="num"><?=num($dispatchItem['requested_qty'])?></td><td class="num"><b><?=num($dispatchItem['approved_qty'])?></b></td><td><?=h($dispatchItem['unit'])?></td></tr><?php endforeach?></tbody></table>
